import{D as d}from"./chunks/donate.3a95be8c.js";import{o as e,c as a,O as o,X as t}from"./chunks/framework.7fab6bae.js";import"./chunks/wcpay.d0e1a780.js";const r=t('<h1 id="紫微斗数星曜系统" tabindex="-1">자미두수 성요 체계（紫微斗數星曜系統） <a class="header-anchor" href="#紫微斗数星曜系统" aria-label="Permalink to &quot;자미두수 성요 체계（紫微斗數星曜系統）   {#紫微斗数星曜系统}&quot;">​</a></h1><h2 id="前言" tabindex="-1">서문 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;서문   {#前言}&quot;">​</a></h2><p>자미두수（紫微斗數）의 성요（星曜） 체계는 조합이 많아 복잡합니다. 하지만 전부 외울 필요는 없습니다. 각 성요를 사람처럼 생각하고 핵심 특성을 기억한 뒤, 그 특성에서 다른 모습을 유추하면 이해하기 쉽습니다. 고정 성요는 <code>117</code>개, 유요（流曜）는 <code>21</code>개이며, 여기에는 사화성（四化星）의 비화 경우를 따로 세지 않았습니다. 일부 성요를 자세히 익히고 나머지는 유형별로 묶어 기억하면 됩니다.</p><p>117개 성요는 <a href="./major-star"><code>14 주성</code></a>, <a href="./minor-star"><code>보조 별 14개</code></a>, <a href="./adj-star"><code>37 잡요</code></a>, <a href="./dec-star"><code>48 신살</code>（48神煞）</a>, <a href="./mutagen"><code>사화성</code>（四化星）</a>으로 나뉩니다. 사화성은 네 가지뿐이지만 체계에서 가장 복잡한 부분이므로 별도의 장에서 설명합니다. 이 장에서는 사화성을 제외한 성요를 소개합니다.</p><blockquote><p><em>이 연재는 저자가 직접 쓴 글입니다. 다른 곳에 옮길 때는 출처를 밝혀 주세요.</em></p></blockquote>',5),c=t('<h2 id="十四主星" tabindex="-1">열네 주성 <a class="header-anchor" href="#十四主星" aria-label="Permalink to &quot;열네 주성 {#十四主星}&quot;">​</a></h2><p><a href="./major-star">14주성（十四主星）</a>은 14개의 <code>정요</code>（正曜）라고도 합니다. <code>주성</code>（主星）은 명반에서 <code>주요</code> 역할을 맡습니다. 주성이 하는 일은 궁의 <code>전체 성향을 정하는 것</code>입니다. 궁을 <code>교실</code>에 비유하면 주성은 <code>선생님</code>입니다. 학급이 중국어나 영어 중 무엇을 잘하느냐는 교사가 어떤 과목을 잘 가르치는지에 달려 있습니다. 14개 성요는 <code>자미</code>（紫微）와 <code>천부</code>（天府）가 이끄는 두 팀으로 나뉩니다. 전체 위치를 정하려면 먼저 자미（紫微）의 위치를 정해야 합니다. 배치 방법은 <a href="./setup#_8-起紫微星诀">자미성 배치 규칙（起紫微星訣）</a>을 참고하세요.</p><p><code>자미</code>（紫微） 팀에는 6명의 멤버가 있습니다:</p><ul><li>자미（紫微）</li><li>천기（天機）</li><li>태양（太陽）</li><li>무곡（武曲）</li><li>천동（天同）</li><li>염정（廉貞）</li></ul><p><code>천부</code>（天府） 팀에는 다음 여덟 성요가 있습니다:</p><ul><li>천부（天府）</li><li>태음（太陰）</li><li>탐랑（貪狼）</li><li>거문（巨門）</li><li>천상（天相）</li><li>천량（天梁）</li><li>칠살（七殺）</li><li>파군（破軍）</li></ul><h2 id="十四辅星" tabindex="-1">열네 보조성（輔星） <a class="header-anchor" href="#十四辅星" aria-label="Permalink to &quot;열네 보조성（輔星） {#十四辅星}&quot;">​</a></h2><p><a href="./minor-star">14보조성（十四輔星）</a>은 <code>학급 임원</code> 역할을 합니다. <code>공궁</code>（空宮）에 <code>보조성</code>（輔星）이 있으면 주성의 제약이 없어 그 보조성의 특성이 더 뚜렷해집니다. 14보조성은 <code>육길성</code>（六吉星）, <code>육살성</code>（六煞星）, <code>두 조성</code>（二助星）의 세 유형으로 나뉩니다.</p><div class="tip custom-block"><p class="custom-block-title">팁</p><p><code>길성</code>（吉星）과 <code>살성</code>（煞星）은 옛사람들이 붙인 분류이며, 오늘날에는 그 구분에만 얽매이지 않아야 합니다. 길성은 사교적이고 친근하게 느껴지는 반면, 살성은 관습을 따르지 않아 덜 어울리는 것처럼 보일 수 있습니다. 하지만 “겉모습만으로 사람을 판단할 수 없다”는 말(<code>人不可貌相</code>)처럼 성요도 겉모습만으로 판단할 수 없습니다. <code>길성</code>（吉星）이라고 모두 좋은 것도, <code>살성</code>（煞星）이라고 모두 나쁜 것도 아닙니다.</p></div><h2 id="三十七杂曜" tabindex="-1">서른일곱 잡요（雜曜） <a class="header-anchor" href="#三十七杂曜" aria-label="Permalink to &quot;서른일곱 잡요（雜曜） {#三十七杂曜}&quot;">​</a></h2><p>자미두수（紫微斗數）에는 <a href="./adj-star">잡요（雜曜）</a>가 많으므로 유형별로 묶어 기억하면 좋습니다. 같은 유형은 대체로 역할과 의미가 비슷합니다. 앞의 학급 비유에서 <code>주성</code>（主星）은 <code>선생님</code>, <code>보조성</code>（輔星）은 <code>학급 임원</code>, <code>잡요</code>（雜曜）는 <code>학생</code>에 해당하며, 함께 학급, 즉 궁의 특징을 만듭니다. 게임에 비유하면 주성은 <code>캐릭터</code>, 보조성은 <code>장비</code>, 잡요는 <code>강화 효과</code>나 <code>약화 효과</code>입니다. 잡요는 다음 아홉 유형으로 나눌 수 있습니다:</p><ul><li><a href="./adj-star#交际类">사교</a></li><li><a href="./adj-star#孤傲类">고고함</a></li><li><a href="./adj-star#才艺类">예술과 재능</a></li><li><a href="./adj-star#矜贵类">품격과 지위</a></li><li><a href="./adj-star#精神类">내면</a></li><li><a href="./adj-star#幸运类">행운</a></li><li><a href="./adj-star#健康类">건강</a></li><li><a href="./adj-star#封赏类">포상</a></li><li><a href="./adj-star#思想类">사고와 성찰</a></li></ul><h2 id="四十八神煞" tabindex="-1">마흔여덟 신살（神煞） <a class="header-anchor" href="#四十八神煞" aria-label="Permalink to &quot;마흔여덟 신살（神煞） {#四十八神煞}&quot;">​</a></h2><p>신살（神煞）은 출생 시 궁위에 고정되는 것과 유년 명궁（流年命宮）을 따라 이동하는 것으로 나뉩니다. 48신살은 보통 독립적으로 작용하지 않습니다. 잡요보다 <code>추가 속성</code>에 가까우며, 주로 <code>정신력</code>이나 <code>기질</code>로 나타납니다. 게임 장비의 <code>인챈트</code>나 장착하는 <code>룬</code>처럼 특정 <code>속성</code>을 높이거나 낮추는 효과로 생각하면 됩니다. 아직 명반 해석에 익숙하지 않다면 신살 해석은 잠시 생략해도 됩니다.</p><ul><li><a href="./dec-star#长生12神">장생 십이신（長生十二神）</a></li><li><a href="./dec-star#博士12神">박사 십이신（博士十二神）</a></li><li><a href="./dec-star#将前12神">장전 십이신（將前十二神）</a></li><li><a href="./dec-star#岁前12神">세전 십이신（歲前十二神）</a></li></ul><div class="info custom-block"><p class="custom-block-title">팁</p><p><a href="./major-star">14주성（十四主星）</a>과 <a href="./minor-star">14보조성（十四輔星）</a>을 소개할 때 각 성요에 다음 정보를 담은 작은 소개 카드를 제공합니다:</p><ul><li><p><a href="./basis#阴阳五行">음양（陰陽）오행（五行）</a></p><p>성요의 음양（陰陽）과 오행（五行）은 혈액형으로 성격을 이야기할 때처럼 대략적인 특징을 나타냅니다. 비슷한 성격의 성요끼리 비교하면, 이 차이를 더 뚜렷하게 느낄 수 있습니다.</p></li><li><p>성계 구분</p><p>성요는 <code>중천 성계</code>（中天星系）, <code>남두 성계</code>（南斗星系）, <code>북두 성계</code>（北斗星系）로 나뉩니다. 명반 해석에 미치는 영향은 무시할 만큼 작으며, 배경 지식을 익히거나 더 깊이 연구할 때 참고하는 구분입니다.</p></li><li><p>상징적 성질</p><p>화기（化氣）는 어떤 것을 태운 뒤 마지막에 남는 것을 본질에 비유한 표현입니다. 여기서는 성요의 핵심적인 성질을 뜻합니다. <code>상징적 성질</code>을 알면 성요의 특징을 빠르게 기억할 수 있습니다.</p></li><li><p>오행의 색</p><p>오행의 색은 명반 해석에 영향을 주지 않습니다. 설명을 빠짐없이 갖추기 위해 학습 노트에 적어 둔 내용을 소개하지만, 출처는 기억나지 않습니다.</p></li><li><p>에너지 색</p><p><code>오행의 색</code>에 대한 설명과 같습니다.</p></li><li><p>직업</p><p>여기서 말하는 직업은 명반 주인의 실제 직업이 아니라 별의 상징적인 역할입니다. 사회적 역할에 비유하여 그 별이 담당하는 영역을 빠르게 이해하도록 돕습니다.</p></li><li><p>역할</p><p><code>직업</code>과 마찬가지로, 여기서 말하는 직무는 성요의 특징을 큰 틀에서 정리한 것입니다.</p></li><li><p>별칭</p><p>후대 사람들이 성요의 특성에 따라 붙인 별명입니다. <code>별칭</code>을 기억하면 성요의 성질을 더 빨리 익힐 수 있습니다.</p></li></ul></div><h2 id="星曜的亮度" tabindex="-1">별의 밝기 <a class="header-anchor" href="#星曜的亮度" aria-label="Permalink to &quot;별의 밝기   {#星曜的亮度}&quot;">​</a></h2><p>자미두수（紫微斗數）의 성요 밝기（星曜亮度） 개념은 빛의 세기에 따라 사람이 받는 느낌에서 비롯됩니다. 한낮의 햇빛은 뜨겁고 눈부시지만, 해 질 무렵에는 훨씬 온화하게 느껴집니다. 그래서 낙함한 태양（太陽）은 태음（太陰）과 비슷하고, 묘왕한 태음은 태양과 비슷하다고 말합니다.</p><p>자미두수（紫微斗數）에서는 유파마다 밝기 등급을 조금 다르게 정합니다.</p><p>일부 유파는 밝기를 <code>[+3]</code>（廟）, <code>[+2]</code>（旺）, <code>[0]</code>（利）, <code>[-3]</code>（陷）의 네 등급으로 나눕니다.</p><p>다른 유파는 밝기를 <code>[+3]</code>（廟）, <code>[+2]</code>（旺）, <code>[+1]</code>（得）, <code>[0]</code>（利）, <code>[-1]</code>（平）, <code>[-2]</code>（不）, <code>[-3]</code>（陷）의 일곱 등급으로 나눕니다.</p><p><code>[+3]</code>（廟）가 가장 밝고 <code>[-3]</code>（陷）이 가장 어둡습니다. 자미두수（紫微斗數）에서 밝기는 성요가 자신의 특성을 드러내려는 정도로 이해할 수 있습니다. 밝을수록 적극적으로 드러내고, 어두울수록 소극적으로 나타납니다. 예를 들어 묘왕한 탐랑（貪狼）은 욕구를 더 적극적으로 추구하지만, 낙함한 탐랑은 욕구를 마음속에 두거나 실행하기 전에 더 많이 고민합니다. 묘왕한 태양（太陽）은 권한을 적극적이고 직접적으로 추구하고, 낙함한 태양은 더 온화합니다.</p><div class="tip custom-block"><p class="custom-block-title">팁</p><p>자미두수（紫微斗數）의 성격 차이는 비교할 때 더 분명해집니다. 무곡（武曲）은 고집이 강하지만, 같은 무곡이라도 신궁（身宮）이 명궁（命宮）에 있으면 더 강합니다. 여기에 무곡이 화권（化權）까지 하면 고집은 더욱 강해집니다.</p></div><h3 id="星曜亮度表" tabindex="-1">별 밝기 표 <a class="header-anchor" href="#星曜亮度表" aria-label="Permalink to &quot;별 밝기 표   {#星曜亮度表}&quot;">​</a></h3><table><thead><tr><th>성요（星曜）</th><th>인（寅）</th><th>묘（卯）</th><th>진（辰）</th><th>사（巳）</th><th>오（午）</th><th>미（未）</th><th>신（申）</th><th>유（酉）</th><th>술（戌）</th><th>해（亥）</th><th>자（子）</th><th>축（丑）</th></tr></thead><tbody><tr><td>자미（紫微）</td><td>[+2]（旺）</td><td>[+2]（旺）</td><td>[+1]（得）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[+3]（廟）</td><td>[+2]（旺）</td><td>[+2]（旺）</td><td>[+1]（得）</td><td>[+2]（旺）</td><td>[-1]（平）</td><td>[+3]（廟）</td></tr><tr><td>천기（天機）</td><td>[+1]（得）</td><td>[+2]（旺）</td><td>[0]（利）</td><td>[-1]（平）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+2]（旺）</td><td>[0]（利）</td><td>[-1]（平）</td><td>[+3]（廟）</td><td>[-3]（陷）</td></tr><tr><td>태양（太陽）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[+2]（旺）</td><td>[+2]（旺）</td><td>[+2]（旺）</td><td>[+1]（得）</td><td>[+1]（得）</td><td>[-1]（平）</td><td>[-2]（不）</td><td>[-3]（陷）</td><td>[-3]（陷）</td><td>[-2]（不）</td></tr><tr><td>무곡（武曲）</td><td>[+1]（得）</td><td>[0]（利）</td><td>[+3]（廟）</td><td>[-1]（平）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[+1]（得）</td><td>[0]（利）</td><td>[+3]（廟）</td><td>[-1]（平）</td><td>[+2]（旺）</td><td>[+3]（廟）</td></tr><tr><td>천동（天同）</td><td>[0]（利）</td><td>[-1]（平）</td><td>[-1]（平）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[-2]（不）</td><td>[+2]（旺）</td><td>[-1]（平）</td><td>[-1]（平）</td><td>[+3]（廟）</td><td>[+2]（旺）</td><td>[-2]（不）</td></tr><tr><td>염정（廉貞）</td><td>[+3]（廟）</td><td>[-1]（平）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[-1]（平）</td><td>[0]（利）</td><td>[+3]（廟）</td><td>[-1]（平）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[-1]（平）</td><td>[0]（利）</td></tr><tr><td>천부（天府）</td><td>[+3]（廟）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[+1]（得）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[+1]（得）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[+3]（廟）</td></tr><tr><td>태음（太陰）</td><td>[+2]（旺）</td><td>[-3]（陷）</td><td>[-3]（陷）</td><td>[-3]（陷）</td><td>[-2]（不）</td><td>[-2]（不）</td><td>[0]（利）</td><td>[+2]（旺）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[+3]（廟）</td><td>[+3]（廟）</td></tr><tr><td>탐랑（貪狼）</td><td>[-1]（平）</td><td>[0]（利）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[-1]（平）</td><td>[0]（利）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[+3]（廟）</td></tr><tr><td>거문（巨門）</td><td>[+3]（廟）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[+2]（旺）</td><td>[-2]（不）</td><td>[+3]（廟）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[+2]（旺）</td><td>[-2]（不）</td></tr><tr><td>천상（天相）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[+3]（廟）</td></tr><tr><td>천량（天梁）</td><td>[+3]（廟）</td><td>[+3]（廟）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+3]（廟）</td><td>[+2]（旺）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+3]（廟）</td><td>[+2]（旺）</td></tr><tr><td>칠살（七殺）</td><td>[+3]（廟）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[-1]（平）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[+3]（廟）</td><td>[+2]（旺）</td><td>[+3]（廟）</td><td>[-1]（平）</td><td>[+2]（旺）</td><td>[+3]（廟）</td></tr><tr><td>파군（破軍）</td><td>[+1]（得）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[-1]（平）</td><td>[+3]（廟）</td><td>[+2]（旺）</td><td>[+1]（得）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[-1]（平）</td><td>[+3]（廟）</td><td>[+2]（旺）</td></tr><tr><td>문창（文昌）</td><td>[-3]（陷）</td><td>[0]（利）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[0]（利）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[0]（利）</td><td>[+1]（得）</td><td>[+3]（廟）</td></tr><tr><td>문곡（文曲）</td><td>[-1]（平）</td><td>[+2]（旺）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>[+2]（旺）</td><td>[+1]（得）</td><td>[+3]（廟）</td></tr><tr><td>화성（火星）</td><td>[+3]（廟）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[+1]（得）</td></tr><tr><td>영성（鈴星）</td><td>[+3]（廟）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[+1]（得）</td><td>[+3]（廟）</td><td>[0]（利）</td><td>[-3]（陷）</td><td>[+1]（得）</td></tr><tr><td>경양（擎羊）</td><td>-</td><td>[-3]（陷）</td><td>[+3]（廟）</td><td>-</td><td>[-3]（陷）</td><td>[+3]（廟）</td><td>-</td><td>[-3]（陷）</td><td>[+3]（廟）</td><td>-</td><td>[-3]（陷）</td><td>[+3]（廟）</td></tr><tr><td>타라（陀羅）</td><td>[-3]（陷）</td><td>-</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>-</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>-</td><td>[+3]（廟）</td><td>[-3]（陷）</td><td>-</td><td>[+3]（廟）</td></tr></tbody></table><h2 id="流曜" tabindex="-1">유요（流曜） <a class="header-anchor" href="#流曜" aria-label="Permalink to &quot;유요（流曜）   {#流曜}&quot;">​</a></h2><p>유요（流曜）는 시간에 따라 변하며, 본명 성요（本命星曜）에서 파생됩니다. 이 체계에서는 대한（大限）과 유년（流年）의 유요만 다루지만, 다른 운한에도 유요를 배치하는 유파가 있습니다. 작용 범위는 해당 운한에만 한정됩니다. 중국어 이름에서는 대한 유요 앞에 運, 유년 유요 앞에 流를 붙여 구분합니다. 대한에는 해신（解神）이 없으며, 유년의 해신은 <code>해신(년)</code>（年解）이라고 합니다.</p><p>유파마다 유요（流曜）를 사용하는 방식이 달라, 이 프로그램은 각 유파가 필요에 따라 선택할 수 있도록 최대한 빠짐없이 제공합니다. 누락된 유요가 있다면 위챗(iztroi)에서 저를 친구로 추가해 알려 주세요. 감사하겠습니다. 현재 시간에 따라 변하는 성요는 다음과 같습니다:</p><ul><li>천괴（天魁）</li><li>천월（天鉞）</li><li>문창（文昌）</li><li>문곡（文曲）</li><li>홍란（紅鸞）</li><li>천희（天喜）</li><li>록존（祿存）</li><li>경양（擎羊）</li><li>타라（陀羅）</li><li>천마（天馬）</li><li>해신（解神）</li><li>사화（四化）</li></ul>',29),_=JSON.pars